class Solution {
public:
    int countMagicalPairs(string s) {
        int n = (int)s.size();
        const int MAXD = 26;
        vector<vector<int>> right(n + 1, vector<int>(MAXD + 1, 0));

        // pre‑compute right[start][d]
        for (int start = 0; start < n; ++start) {
            int freq[26] = {0};
            int distinct = 0;
            for (int end = start; end < n; ++end) {
                int c = s[end] - 'a';
                if (freq[c] == 0) ++distinct;
                ++freq[c];
                ++right[start][distinct];
            }
        }

        long long ans = 0;
        // enumerate left substrings
        for (int i = 0; i < n - 1; ++i) {
            int freq[26] = {0};
            int distinct = 0;
            for (int j = i; j < n - 1; ++j) { // j+1 must be < n
                int c = s[j] - 'a';
                if (freq[c] == 0) ++distinct;
                ++freq[c];
                ans += right[j + 1][distinct];
            }
        }
        return (int)ans;
    }
};
